const body = $input.first().json.body;
const type = body.type || 'booking';
const lang = (body.language || 'es').toLowerCase();
const name = body.patient_name || 'Paciente';
const email = String(body.patient_email || '');
const doctor = body.doctor_name || '';
const specialty = body.specialty || '';
const date = body.date || '';
const time = body.time || '';
const apptId = body.appointment_id || '';
const clinicPhone = '+34 91 345 17 57';
const clinicAddress = 'Calle Doctor Esquerdo 16, Madrid';

const row = (label, val, alt) => `<tr style="background:${alt?'#f9fafb':'#fff'}"><td style="padding:10px 14px;color:#6b7280;width:40%">${label}</td><td style="padding:10px 14px;font-weight:500">${val}</td></tr>`;

let subject = '', html = '';

if (lang === 'es') {
  if (type === 'booking') {
    subject = `✅ Cita confirmada — ${apptId} | Clínica Masoumi`;
    html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#1d4ed8;color:#fff;padding:24px;text-align:center"><h2 style="margin:0">Clínica Masoumi</h2><p style="margin:6px 0 0;opacity:.85">Confirmación de Cita</p></div><div style="padding:24px"><p>Hola <strong>${name}</strong>,</p><p>Su cita ha sido confirmada exitosamente.</p><table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden">${row('Código de Cita','<span style="font-family:monospace;background:#eff6ff;padding:2px 8px;border-radius:4px">'+apptId+'</span>',false)}${row('Doctor',doctor,true)}${row('Especialidad',specialty,false)}${row('Fecha',date,true)}${row('Hora',time,false)}${row('Duración','45 minutos',true)}${row('Dirección',clinicAddress,false)}</table><p style="margin-top:20px">Para cancelar o reagendar llame al <strong>${clinicPhone}</strong>.</p></div><div style="background:#f3f4f6;padding:14px;text-align:center;font-size:12px;color:#9ca3af">Clínica Masoumi · ${clinicAddress} · ${clinicPhone}</div></div>`;
  } else if (type === 'cancel') {
    subject = `❌ Cita cancelada | Clínica Masoumi`;
    html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#dc2626;color:#fff;padding:24px;text-align:center"><h2 style="margin:0">Clínica Masoumi</h2><p style="margin:6px 0 0;opacity:.85">Cita Cancelada</p></div><div style="padding:24px"><p>Hola <strong>${name}</strong>,</p><p>Su cita con <strong>${doctor}</strong> del <strong>${date} a las ${time}</strong> ha sido cancelada correctamente.</p><p>Para nueva cita llame al <strong>${clinicPhone}</strong>.</p></div><div style="background:#f3f4f6;padding:14px;text-align:center;font-size:12px;color:#9ca3af">Clínica Masoumi · ${clinicAddress}</div></div>`;
  } else {
    subject = `🔄 Cita reprogramada — ${apptId} | Clínica Masoumi`;
    html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#059669;color:#fff;padding:24px;text-align:center"><h2 style="margin:0">Clínica Masoumi</h2><p style="margin:6px 0 0;opacity:.85">Cita Reprogramada</p></div><div style="padding:24px"><p>Hola <strong>${name}</strong>,</p><p>Su cita ha sido reprogramada.</p><table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb">${row('Código',apptId,false)}${row('Doctor',doctor,true)}${row('Nueva Fecha',date,false)}${row('Nueva Hora',time,true)}</table><p style="margin-top:20px">Para cambios llame al <strong>${clinicPhone}</strong>.</p></div><div style="background:#f3f4f6;padding:14px;text-align:center;font-size:12px;color:#9ca3af">Clínica Masoumi · ${clinicAddress}</div></div>`;
  }
} else {
  if (type === 'booking') {
    subject = `✅ Appointment Confirmed — ${apptId} | Masoumi Clinic`;
    html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#1d4ed8;color:#fff;padding:24px;text-align:center"><h2 style="margin:0">Masoumi Clinic</h2><p style="margin:6px 0 0;opacity:.85">Appointment Confirmation</p></div><div style="padding:24px"><p>Hello <strong>${name}</strong>,</p><p>Your appointment has been confirmed.</p><table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden">${row('Appointment Code','<span style="font-family:monospace;background:#eff6ff;padding:2px 8px;border-radius:4px">'+apptId+'</span>',false)}${row('Doctor',doctor,true)}${row('Specialty',specialty,false)}${row('Date',date,true)}${row('Time',time,false)}${row('Duration','45 minutes',true)}${row('Address',clinicAddress,false)}</table><p style="margin-top:20px">To cancel or reschedule, call <strong>${clinicPhone}</strong>.</p></div><div style="background:#f3f4f6;padding:14px;text-align:center;font-size:12px;color:#9ca3af">Masoumi Clinic · ${clinicAddress} · ${clinicPhone}</div></div>`;
  } else if (type === 'cancel') {
    subject = `❌ Appointment Cancelled | Masoumi Clinic`;
    html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#dc2626;color:#fff;padding:24px;text-align:center"><h2 style="margin:0">Masoumi Clinic</h2><p style="margin:6px 0 0;opacity:.85">Appointment Cancelled</p></div><div style="padding:24px"><p>Hello <strong>${name}</strong>,</p><p>Your appointment with <strong>${doctor}</strong> on <strong>${date} at ${time}</strong> has been cancelled.</p><p>To book again, call <strong>${clinicPhone}</strong>.</p></div><div style="background:#f3f4f6;padding:14px;text-align:center;font-size:12px;color:#9ca3af">Masoumi Clinic · ${clinicAddress}</div></div>`;
  } else {
    subject = `🔄 Appointment Rescheduled — ${apptId} | Masoumi Clinic`;
    html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden"><div style="background:#059669;color:#fff;padding:24px;text-align:center"><h2 style="margin:0">Masoumi Clinic</h2><p style="margin:6px 0 0;opacity:.85">Appointment Rescheduled</p></div><div style="padding:24px"><p>Hello <strong>${name}</strong>,</p><p>Your appointment has been rescheduled.</p><table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb">${row('Code',apptId,false)}${row('Doctor',doctor,true)}${row('New Date',date,false)}${row('New Time',time,true)}</table><p style="margin-top:20px">For further changes, call <strong>${clinicPhone}</strong>.</p></div><div style="background:#f3f4f6;padding:14px;text-align:center;font-size:12px;color:#9ca3af">Masoumi Clinic · ${clinicAddress}</div></div>`;
  }
}

return [{ json: { email_to: email, email_subject: subject, email_body: html, patient_name: name, type } }];
